//
// Book Store: compute the cheapest price (in cents) for a basket of books
// from a 5-book series, applying the best possible set of multi-book discounts.
//

const UNIT_PRICE = 800; // one copy of any book costs $8.00

// percentage discount applied to a group of N *different* books
const DISCOUNT_PERCENT = { 1: 0, 2: 5, 3: 10, 4: 20, 5: 25 };

// price in cents of a single group of `size` different books
const groupPrice = (size) =>
  (size * UNIT_PRICE * (100 - DISCOUNT_PERCENT[size])) / 100;

// Books are interchangeable, so a basket is fully described by how many
// copies of each title remain.  Canonical form: counts sorted descending.
const canonicalKey = (counts) => counts.slice().sort((a, b) => b - a).join(',');

export const cost = (books) => {
  const counts = [0, 0, 0, 0, 0];
  for (const book of books) {
    counts[book - 1] += 1;
  }

  const memo = new Map();

  const cheapest = (state) => {
    if (state.every((count) => count === 0)) {
      return 0;
    }

    const key = canonicalKey(state);
    if (memo.has(key)) {
      return memo.get(key);
    }

    const available = state.filter((count) => count > 0).length;
    const sorted = state.slice().sort((a, b) => b - a);

    let best = Infinity;
    for (let size = 1; size <= available; size += 1) {
      // Taking the `size` most plentiful titles for this group is always
      // at least as good as any other subset of the same size.
      const next = sorted.slice();
      for (let i = 0; i < size; i += 1) {
        next[i] -= 1;
      }
      best = Math.min(best, groupPrice(size) + cheapest(next));
    }

    memo.set(key, best);
    return best;
  };

  return cheapest(counts);
};
